#!/usr/bin/env bun
// Assemble the `build` branch tree: the one generated delivery channel the
// fleet consumes, for BOTH copier renders and `uses:` action refs.
//
// Layout at the branch root:
//
// - copier.yml       (byte copy from this checkout's root; its generated
//                     _exclude region carries the conditional-landing gates)
// - template/        (composed from templates/ via compose_template.build -
//                     PLAIN filenames only; build() refuses a tree whose
//                     copier.yml excludes are stale)
// - actions/         (the composite actions' sources + dependency manifests,
//                     node_modules and build output excluded - each action
//                     installs at its own action_path when it runs)
// - stamp_manifest.ts (the manifest stamping hook copier.yml's _tasks and
//                     _migrations run; byte copy of .github/scripts/sync's)
// - README.md        (static explainer)
//
// One branch serves both consumers because the whole tree is
// extraction-safe: a `uses: <owner>/repo-platform/actions/<name>@build`
// ref downloads the branch tarball, and extraction dies on
// jinja-expression path segments - which the composed tree no longer
// carries (tests/build-branches pins that invariant over the full tree).
//
// Content is fully deterministic - no timestamps or source SHAs in-tree, so
// the append-only build branch only gains a commit when something real
// changed (provenance lives in the build commit message instead). No .github/
// is included: nothing may trigger on the build branch.
//
// Usage:
//   bun .github/scripts/build-branches/branch_tree.ts --dest DIR

import {
  cpSync,
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { basename, dirname, join, resolve } from "node:path";
import { build, writeOutput } from "../../../scripts/compose_template.ts";

const REPO_ROOT = resolve(import.meta.dir, "..", "..", "..");

/** The path with every EXISTING component dereferenced: resolve() is
 * lexical, so a symlinked parent (say /tmp/projects -> the repo's parent)
 * would otherwise alias the checkout past the overlap guard below. The
 * not-yet-existing tail is re-attached unresolved. */
export function canonicalize(path: string): string {
  let base = path;
  const tail: string[] = [];
  while (!existsSync(base)) {
    tail.unshift(basename(base));
    const parent = dirname(base);
    if (parent === base) break;
    base = parent;
  }
  return join(realpathSync(base), ...tail);
}

const README = `\
# repo-platform build branch

This branch is GENERATED by the build-branches workflow on \`main\` - do not
commit to it or open pull requests against it (they are closed automatically).
Template sources live in \`templates/\` on \`main\`, the composite actions'
sources in \`actions/\`.

\`build\` is rebuilt from each \`main\` commit whose CI run succeeds (the
branch ships only green main commits). It carries the composed copier tree
under \`template/\` and the composite actions under \`actions/\` - every
path is extraction-safe (no jinja-expression filenames), so
\`uses: <owner>/repo-platform/actions/<name>@build\` refs extract cleanly
on the runner, and an @build pin runs only action code CI has vouched for.

Consume the template with copier, e.g.:

    copier copy gh:Vivswan/repo-platform . --vcs-ref build
`;

/** Directories never published under actions/: build output and installed
 *  dependencies, both reproducible from what is published. */
export const EXCLUDED_DIRS = new Set(["node_modules", "dist", ".turbo"]);

/** Copies every action directory to `<dest>/actions`, returning the number
 *  of files written. Throws when the source has no actions at all: the
 *  rendered workflows reference them by path, so publishing a branch
 *  without them would 404 every fleet CI run rather than fail here. */
export function copyActions(repoRoot: string, dest: string): number {
  const source = join(repoRoot, "actions");
  if (!existsSync(source)) {
    throw new Error(
      `no actions/ directory at ${repoRoot} - the rendered workflows call ` +
        "actions by path, so a build branch without them breaks every " +
        "fleet CI run; check the checkout before publishing",
    );
  }
  const names = readdirSync(source, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && !EXCLUDED_DIRS.has(entry.name))
    .map((entry) => entry.name)
    .sort();
  if (names.length === 0) {
    throw new Error(`actions/ at ${repoRoot} holds no action directories`);
  }
  let files = 0;
  for (const name of names) {
    cpSync(join(source, name), join(dest, "actions", name), {
      recursive: true,
      filter: (src) => {
        const segments = src.split("/");
        return !segments.some((segment) => EXCLUDED_DIRS.has(segment));
      },
    });
    files += countFiles(join(dest, "actions", name));
  }
  return files;
}

function countFiles(dir: string): number {
  let total = 0;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    total += entry.isDirectory() ? countFiles(join(dir, entry.name)) : 1;
  }
  return total;
}

/** Assemble the whole branch tree at `dest` (which must exist and be
 *  empty): the composed template/, actions/, copier.yml, the stamp hook,
 *  and the README. Exported for the extraction-safety regression, which
 *  asserts no assembled path carries a jinja expression. */
export function assembleBranchTree(dest: string): void {
  const composed = build();
  writeOutput(composed, join(dest, "template"));
  copyActions(REPO_ROOT, dest);
  writeFileSync(join(dest, "copier.yml"), readFileSync(join(REPO_ROOT, "copier.yml")));
  writeFileSync(
    join(dest, "stamp_manifest.ts"),
    readFileSync(join(REPO_ROOT, ".github", "scripts", "sync", "stamp_manifest.ts")),
  );
  writeFileSync(join(dest, "README.md"), README);
}

function usageError(message: string): never {
  console.error(`error: ${message}`);
  process.exit(2);
}

function parseArgs(argv: string[]): { dest: string } {
  let dest: string | undefined;
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    const value = () => {
      i++;
      if (i >= argv.length) usageError(`argument ${arg}: expected one argument`);
      return argv[i];
    };
    if (arg === "--dest") dest = value();
    else usageError(`unrecognized argument: ${arg}`);
  }
  if (!dest) usageError("the following arguments are required: --dest");
  return { dest };
}

/** True when dest is the repository root, an ancestor of it, or inside it -
 * every path whose recursive removal would take the checkout with it. A
 * dest of "/" must not slip past the ancestor check because "/" + "/" is
 * "//", which no absolute path starts with. */
export function destOverlapsRepo(dest: string, repoRoot: string): boolean {
  const destPrefix = dest.endsWith("/") ? dest : `${dest}/`;
  return dest === repoRoot || repoRoot.startsWith(destPrefix) || dest.startsWith(`${repoRoot}/`);
}

function main(): number {
  const args = parseArgs(process.argv.slice(2));

  const dest = resolve(args.dest);
  // Compare canonically - a symlinked parent must not alias the checkout
  // past the guard - but mutate the lexical path: canonicalizing dest for
  // rmSync would dereference a symlinked dest and delete its TARGET
  // instead of replacing the link.
  if (destOverlapsRepo(canonicalize(dest), canonicalize(REPO_ROOT))) {
    usageError(
      `--dest ${dest} is inside the repository and would be wiped along ` +
        "with the checkout; pass a path outside it, e.g. --dest /tmp/build-tree",
    );
  }
  if (existsSync(dest)) rmSync(dest, { recursive: true });
  mkdirSync(dest, { recursive: true });

  assembleBranchTree(dest);

  console.log(`assembled the build tree into ${dest}`);
  return 0;
}

if (import.meta.main) {
  process.exit(main());
}
